const moscowTime = new Intl.DateTimeFormat("en-GB", {
  timeZone: "Europe/Moscow",
  hour: "2-digit",
  minute: "2-digit",
  second: "2-digit",
  hour12: false,
});

export function initializeClock(element) {
  const update = () => {
    element.textContent = moscowTime.format(new Date());
  };

  update();
  const intervalId = window.setInterval(update, 1000);
  return () => window.clearInterval(intervalId);
}
