import "./../static/fonts/NewSpirit.woff2";
import "./../static/fonts/arialnarrow-subset.woff2";
import "./style.css";
import { initializeClock } from "./header/header.js";
import { initializeAspectRatio } from "./aspect-ratio/aspect-ratio.js";

const cleanups = [
  initializeClock(document.querySelector(".mytime")),
  initializeAspectRatio(
    document.getElementById("resize-container"),
    document.getElementById("resize-value"),
  ),
];

async function initializeApplication() {
  const supportsHover = window.matchMedia("(hover: hover) and (pointer: fine)").matches;
  const preloaderCanvas = document.querySelector("canvas.preloader");
  let preloader;

  if (supportsHover) {
    const [{ initializePreloader }, { default: Menu }] = await Promise.all([
      import("./preloader/preloader.js"),
      import("./hover/menu.js"),
    ]);
    preloader = initializePreloader(preloaderCanvas);
    const menu = new Menu(document.querySelector(".links"));
    cleanups.push(() => menu.destroy(), () => preloader.dispose());
  } else {
    preloaderCanvas.remove();
  }

  try {
    const portrait = await import("./three/me.js");
    const portraitScene = portrait.initializePortrait(
      document.querySelector("canvas.me"),
    );
    cleanups.push(() => portraitScene.dispose());
    await portraitScene.loaded;
  } catch (error) {
    // A static fallback remains usable when optional WebGL scenes fail.
    // eslint-disable-next-line no-console
    console.error("Unable to initialize interactive scenes", error);
  } finally {
    await preloader?.finish();
  }
}

initializeApplication();
window.addEventListener("pagehide", () => cleanups.forEach((cleanup) => cleanup()), {
  once: true,
});
